function validate([dividend, divisor]) {
  const fits = (v) => Number.isInteger(v) && v >= -2147483648 && v <= 2147483647;
  if (!fits(dividend) || !fits(divisor)) return 'Both numbers must be 32-bit signed integers.';
  if (divisor === 0) return 'divisor cannot be 0.';
  return null;
}

