function generate(rand, size) {
  const MIN = -2147483648, MAX = 2147483647;
  const edges = [MIN, MAX, -1, 1, 0, 2, -2, 3, MIN + 1, MAX - 1, 1073741824, -1073741824];
  const pick = (spread) => {
    const r = rand();
    if (r < 0.25) return edges[Math.floor(rand() * edges.length)];
    if (r < 0.6) return Math.floor(rand() * (2 * spread + 1)) - spread;
    return Math.floor(rand() * 4294967296) + MIN + Math.floor(rand() * 2);
  };
  const dividend = pick(size === 'large' ? 1000000 : 100);
  let divisor = pick(size === 'large' ? 1000 : 12);
  if (divisor === 0) divisor = rand() < 0.5 ? 1 : -1;
  return [Math.min(MAX, dividend), Math.min(MAX, divisor)];
